let output;

if ($json.output && typeof $json.output === 'object') {
  output = $json.output;
} else {
  let raw = String($json.output || '');

  // Remove Markdown code fences like ```json ... ```
  raw = raw.replace(/```[\s\S]*?```/g, match => match.replace(/```json?|\```/g, ''));

  const idx = raw.indexOf('{');

  if (idx === -1) {
    output = { response: raw };
  } else {
    const startSlice = raw.slice(idx);
    const last = startSlice.lastIndexOf('}');
    const cleanSlice = last !== -1 ? startSlice.slice(0, last + 1) : startSlice;
    output = JSON.parse(cleanSlice);
  }
}
output.contact_id = $('When Executed by Another Workflow').first().json.contact_id.toString()
output.space_id = "364817"

if (output.complete && $('When Executed by Another Workflow').first().json.complaint_id == null) {
  output.human_intervention = false
  output.team = 'technical'
}

return output;

